/**
 * Production server for DMV app.
 * Serves on HTTPS using the shared web-app certificate generated by setup.sh.
 * SSL_CERT and SSL_KEY env vars point to the mounted cert/key paths.
 */
import https from 'https';
import express from 'express';
import path from 'path';
import fs from 'fs';
import { fileURLToPath } from 'url';
import setupRoutes from './src/setupRoutes.mjs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3000;

const SSL_CERT = process.env.SSL_CERT || '/certs/webapps.crt';
const SSL_KEY  = process.env.SSL_KEY  || '/certs/webapps.key';

console.log('Starting DMV app server (HTTPS)');

// Generate config.js with environment variables
const configContent = `// Runtime environment configuration for DMV App
window.ENV = {
  REACT_APP_ACCOUNT_URL: '${process.env.REACT_APP_ACCOUNT_URL || ''}',
  REACT_APP_W3_ROOT: '${process.env.REACT_APP_W3_ROOT || ''}',
  REACT_APP_DMV_REDIRECT_URL: '${process.env.REACT_APP_DMV_REDIRECT_URL || ''}',
  REACT_APP_CREDENTIAL_SCHEMA_ID: '${process.env.REACT_APP_CREDENTIAL_SCHEMA_ID || ''}',
  REACT_APP_CREDENTIAL_DEFINITION_ID: '${process.env.REACT_APP_CREDENTIAL_DEFINITION_ID || ''}',
  REACT_APP_DMV_AGENT_ID: '${process.env.REACT_APP_DMV_AGENT_ID || ''}'
};`;

const configPath = path.join(__dirname, 'build', 'config.js');
fs.writeFileSync(configPath, configContent);
console.log('Generated config.js with environment variables');

// Apply the proxy/route configuration
setupRoutes(app);

// Serve config.js with correct MIME type
app.get('/config.js', (req, res) => {
  res.setHeader('Content-Type', 'application/javascript');
  res.sendFile(configPath);
});

// Serve static files from the build directory
app.use(express.static(path.join(__dirname, 'build')));

// All other requests return the React app
app.use((req, res) => {
  res.sendFile(path.join(__dirname, 'build', 'index.html'));
});

// Start HTTPS server
const tlsOptions = {
  cert: fs.readFileSync(SSL_CERT),
  key:  fs.readFileSync(SSL_KEY),
};

https.createServer(tlsOptions, app).listen(PORT, () => {
  console.log(`DMV app server running on https://localhost:${PORT}`);
});
